package local.hy320.helperstarter;
import android.content.Context;import java.io.*;import java.net.*;import java.nio.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import javax.net.ssl.*;
/** Adapted from Shizuku AdbClient/AdbPairingClient. Loopback TLS only, bounded packets, fixed read-only command. */
final class LocalAdb implements AutoCloseable {
 private volatile Socket socket;private volatile boolean cancelled;private DataInputStream in;private DataOutputStream out;
 static final int CNXN=0x4e584e43,STLS=0x534c5453,OPEN=0x4e45504f,OKAY=0x59414b4f,WRTE=0x45545257,CLSE=0x45534c43;
 private void open(int port)throws Exception{if(cancelled)throw new IOException("Cancelled");if(port<1||port>65535)throw new IllegalArgumentException("Invalid local port");Socket s=new Socket();socket=s;if(cancelled){s.close();throw new IOException("Cancelled");}s.connect(new InetSocketAddress(InetAddress.getByAddress(new byte[]{127,0,0,1}),port),4000);s.setSoTimeout(6000);s.setTcpNoDelay(true);in=new DataInputStream(s.getInputStream());out=new DataOutputStream(s.getOutputStream());}
 private SSLSocket tls(ClientIdentity identity,String expectedPin,AtomicReference<String> received)throws Exception{Socket plain=socket;SSLSocket ssl=(SSLSocket)identity.tls(expectedPin,received).getSocketFactory().createSocket(plain,"127.0.0.1",plain.getPort(),true);socket=ssl;ssl.setSoTimeout(6000);ssl.startHandshake();in=new DataInputStream(ssl.getInputStream());out=new DataOutputStream(ssl.getOutputStream());return ssl;}
 String pair(Context context,ClientIdentity identity,int port,String code)throws Exception{
 if(code==null||!code.matches("[0-9]{6}"))throw new IllegalArgumentException("Invalid pairing secret");open(port);AtomicReference<String> received=new AtomicReference<>();SSLSocket ssl=tls(identity,null,received);
 byte[] material=org.conscrypt.Conscrypt.exportKeyingMaterial(ssl,"adb-label\0",null,64);if(material==null||material.length!=64)throw new IOException("TLS key export unavailable");byte[] password=new byte[70];System.arraycopy(code.getBytes(java.nio.charset.StandardCharsets.US_ASCII),0,password,0,6);System.arraycopy(material,0,password,6,64);Arrays.fill(material,(byte)0);
 try(PairingContext spake=new PairingContext(true,password)){Arrays.fill(password,(byte)0);pairWrite(0,spake.message());if(!spake.init(pairRead(0)))throw new IOException("Pairing authentication failed");byte[] peer=new byte[8192];peer[0]=0;if(identity.adbPublic.length>8191)throw new IOException("Public identity too large");System.arraycopy(identity.adbPublic,0,peer,1,identity.adbPublic.length);byte[] encrypted=spake.encrypt(peer);Arrays.fill(peer,(byte)0);if(encrypted==null)throw new IOException("Pairing encryption failed");pairWrite(1,encrypted);byte[] result=spake.decrypt(pairRead(1));if(result==null||result.length!=8192||result[0]!=1)throw new IOException("Pairing server confirmation invalid");Arrays.fill(result,(byte)0);if(received.get()==null)throw new IOException("Missing pairing peer");context.getSharedPreferences("identity",0).edit().putString("pair_server_pin",received.get()).putBoolean("paired",true).commit();return received.get();}finally{Arrays.fill(password,(byte)0);}
 }
 private void pairWrite(int type,byte[] bytes)throws IOException{if(bytes.length<1||bytes.length>16384)throw new IOException("Invalid pairing packet");out.writeByte(1);out.writeByte(type);out.writeInt(bytes.length);out.write(bytes);out.flush();}
 private byte[] pairRead(int expected)throws IOException{if(in.readUnsignedByte()!=1||in.readUnsignedByte()!=expected)throw new IOException("Unexpected pairing packet");int length=in.readInt();if(length<1||length>16384)throw new IOException("Invalid pairing size");byte[] payload=new byte[length];in.readFully(payload);return payload;}
 String identityCheck(Context context,ClientIdentity identity,int port)throws Exception{String pin=context.getSharedPreferences("identity",0).getString("connect_server_pin",null);if(pin==null)throw new SecurityException("Pair this local client first");connect(identity,port,pin);String text=shell("id -u; getprop ro.build.id").replace("\r","").trim();if(!text.equals("2000\nProjector_20260713.153921"))throw new SecurityException("Unexpected shell identity or firmware");return "Authenticated local shell: UID 2000; reviewed firmware verified";}
 private final AtomicReference<String> connectedPin=new AtomicReference<>();
 private void connect(ClientIdentity identity,int port,String expectedPin)throws Exception{open(port);write(CNXN,0x01000001,1024*1024,"host::features=shell_v2;\0".getBytes(java.nio.charset.StandardCharsets.UTF_8));Message request=read();if(request.kind!=STLS)throw new IOException("Authenticated TLS required; no legacy fallback");write(STLS,0x01000000,0,new byte[0]);tls(identity,expectedPin,connectedPin);Message greeting=read();if(greeting.kind!=CNXN)throw new IOException("Local client not authorised");if(!new String(greeting.payload,java.nio.charset.StandardCharsets.UTF_8).contains("shell_v2"))throw new IOException("Modern shell transport unavailable");}
 /** A null expected pin is permitted only for a new-boot nonce transaction, confirmed out-of-band by the signed launcher. */
 String startExistingHelper(ClientIdentity identity,int port,String expectedPin,String verifiedCommand)throws Exception{connect(identity,port,expectedPin);shell(verifiedCommand);return connectedPin.get();}
 private String shell(String command)throws Exception{write(OPEN,1,0,("shell,v2,raw:"+command+"\0").getBytes(java.nio.charset.StandardCharsets.UTF_8));Message start=read();if(start.kind!=OKAY||start.b!=1)throw new IOException("Helper shell request refused");int remote=start.a;ByteArrayOutputStream result=new ByteArrayOutputStream();for(int i=0;i<64;i++){Message m=read();if(m.a!=remote||m.b!=1)throw new IOException("Unexpected shell stream");if(m.kind==WRTE){if(result.size()+m.payload.length>8192)throw new IOException("Unexpected output size");result.write(m.payload);write(OKAY,1,remote,new byte[0]);}else if(m.kind==CLSE){write(CLSE,1,remote,new byte[0]);return decodeShell(result.toByteArray());}else throw new IOException("Unexpected shell response");}throw new IOException("Shell response limit");}
 private static String decodeShell(byte[] stream)throws IOException{java.nio.ByteBuffer packets=java.nio.ByteBuffer.wrap(stream).order(java.nio.ByteOrder.LITTLE_ENDIAN);ByteArrayOutputStream output=new ByteArrayOutputStream();boolean exited=false;while(packets.hasRemaining()){if(packets.remaining()<5)throw new IOException("Incomplete shell frame");int type=packets.get()&255,length=packets.getInt();if(length<0||length>packets.remaining()||length>8192||exited)throw new IOException("Invalid shell frame");byte[] payload=new byte[length];packets.get(payload);if(type==1)output.write(payload);else if(type==2){/* No user data is logged from stderr. Nonzero exit is rejected below. */}else if(type==3){if(length!=1&&length!=4)throw new IOException("Invalid shell exit");int status=length==1?payload[0]&255:java.nio.ByteBuffer.wrap(payload).order(java.nio.ByteOrder.LITTLE_ENDIAN).getInt();if(status!=0)throw new IOException("Helper shell exited with "+status);exited=true;}else throw new IOException("Unexpected shell frame");}if(!exited)throw new IOException("Shell completion not confirmed");return new String(output.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}
 private static final class Message{int kind,a,b;byte[] payload;}
 private Message read()throws IOException{byte[] header=new byte[24];in.readFully(header);ByteBuffer b=ByteBuffer.wrap(header).order(ByteOrder.LITTLE_ENDIAN);Message m=new Message();m.kind=b.getInt();m.a=b.getInt();m.b=b.getInt();int length=b.getInt(),checksum=b.getInt(),magic=b.getInt();if(magic!=(m.kind^-1)||length<0||length>1024*1024)throw new IOException("Invalid ADB frame");m.payload=new byte[length];in.readFully(m.payload);return m;}
 private void write(int command,int a,int b,byte[] payload)throws IOException{ByteBuffer packet=ByteBuffer.allocate(24+payload.length).order(ByteOrder.LITTLE_ENDIAN);int sum=0;for(byte value:payload)sum+=value&255;packet.putInt(command).putInt(a).putInt(b).putInt(payload.length).putInt(sum).putInt(command^-1).put(payload);out.write(packet.array());out.flush();}
 public void close(){cancelled=true;Socket s=socket;if(s!=null)try{s.close();}catch(IOException ignored){}}
}
